.darma-loader-tw-download-bar { display: flex; flex-direction: column; align-items: center; gap: calc(var(--loader-size, 140px) * .09); width: var(--loader-size, 140px); }
.darma-loader-tw-download-bar .darma-loader-tw-download-bar__arrow { position: relative; width: calc(var(--loader-size, 140px) * .09); height: calc(var(--loader-size, 140px) * .32); border-radius: 9999px; background: var(--loader-color, #0ea5e9); animation: darma-loader-tw-download-bar-twDown calc(var(--loader-speed, 1s) * 1.5) ease-in-out infinite; }
.darma-loader-tw-download-bar .darma-loader-tw-download-bar__arrow::after { content: ''; position: absolute; bottom: calc(var(--loader-size, 140px) * -.05); left: 50%; width: calc(var(--loader-size, 140px) * .22); height: calc(var(--loader-size, 140px) * .22); margin-left: calc(var(--loader-size, 140px) * -.11); border-right: calc(var(--loader-size, 140px) * .09) solid var(--loader-color, #0ea5e9); border-bottom: calc(var(--loader-size, 140px) * .09) solid var(--loader-color, #0ea5e9); border-radius: calc(var(--loader-size, 140px) * .03); transform: rotate(45deg); }
.darma-loader-tw-download-bar .darma-loader-tw-download-bar__track { width: 100%; height: calc(var(--loader-size, 140px) * .08); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color, #0ea5e9) 20%, transparent); overflow: hidden; }
.darma-loader-tw-download-bar .darma-loader-tw-download-bar__track i { display: block; width: 100%; height: 100%; border-radius: 9999px; background: var(--loader-color, #0ea5e9); transform-origin: left center; animation: darma-loader-tw-download-bar-twFill calc(var(--loader-speed, 1s) * 1.5) ease-in-out infinite; }
@keyframes darma-loader-tw-download-bar-twDown { 0%, 100% { transform: translateY(-14%); opacity: .5; } 55% { transform: translateY(10%); opacity: 1; } }
@keyframes darma-loader-tw-download-bar-twFill { 0% { transform: scaleX(0); } 100% { transform: scaleX(1); } }

